INSERT INTO refeicao (id, calorias, tempo_preparo, modo_preparo, imagem_url, nome) VALUES (1, 220, 10, '1. Quebre os ovos em uma tigela. 2. Bata até ficar homogêneo. 3. Aqueça o azeite. 4. Refogue os legumes. 5. Adicione os ovos. 6. Cozinhe até firmar. 7. Sirva.', 'https://drive.google.com/file/d/1_Ezukv-5cm4KP1Vkbt12edARQL0G5Ial/view', 'Omelete com Legumes');
INSERT INTO refeicao (id, calorias, tempo_preparo, modo_preparo, imagem_url, nome) VALUES (2, 180, 5, '1. Coloque o iogurte na tigela. 2. Corte a banana. 3. Adicione ao iogurte. 4. Acrescente a chia. 5. Misture e sirva.', 'https://drive.google.com/file/d/1sPEt72SQp0cY81djkZhKvxP6_C-kdth8/view', 'Iogurte com Frutas');
INSERT INTO refeicao (id, calorias, tempo_preparo, modo_preparo, imagem_url, nome) VALUES (3, 250, 8, '1. Aqueça a frigideira. 2. Espalhe a tapioca. 3. Aguarde firmar. 4. Adicione o queijo. 5. Dobre. 6. Sirva.', 'https://drive.google.com/file/d/1xbpzD1MHC_SXImYsgqHgbkPPBJnbuavP/view', 'Tapioca com Queijo');
INSERT INTO refeicao (id, calorias, tempo_preparo, modo_preparo, imagem_url, nome) VALUES (4, 210, 5, '1. Corte a banana. 2. Coloque no liquidificador. 3. Adicione leite e aveia. 4. Bata por 1 minuto. 5. Sirva.', 'https://drive.google.com/file/d/1wc5PpPl1EETnd0yv-W6Mofp8Jq1fdzFC/view', 'Vitamina de Banana');
INSERT INTO refeicao (id, calorias, tempo_preparo, modo_preparo, imagem_url, nome) VALUES (5, 400, 25, '1. Tempere o frango. 2. Grelhe por 5-7 min cada lado. 3. Cozinhe o arroz. 4. Prepare a salada. 5. Monte o prato.', 'https://drive.google.com/file/d/18bwglLwymT2CDWrW-GWzGmf40Cd4TrlN/view', 'Frango com Arroz');
INSERT INTO refeicao (id, calorias, tempo_preparo, modo_preparo, imagem_url, nome) VALUES (6, 420, 30, '1. Corte a batata. 2. Cozinhe por 15 min. 3. Tempere a carne. 4. Grelhe por 4-6 min. 5. Sirva.', 'https://drive.google.com/file/d/1iSHlmxPhQ8XIUnKj-7Kox3xPRbgWrzwk/view', 'Carne com Batata Doce');
INSERT INTO refeicao (id, calorias, tempo_preparo, modo_preparo, imagem_url, nome) VALUES (7, 350, 25, '1. Tempere o peixe. 2. Corte os legumes. 3. Coloque na assadeira. 4. Asse por 20 min. 5. Sirva.', 'https://drive.google.com/file/d/1hYujTnTz0EhqvL-EJUP0aXFEutFRLbi1/view', 'Peixe com Legumes');
INSERT INTO refeicao (id, calorias, tempo_preparo, modo_preparo, imagem_url, nome) VALUES (8, 300, 15, '1. Bata os ovos. 2. Refogue os legumes. 3. Adicione os ovos. 4. Cozinhe até firmar. 5. Sirva.', 'https://drive.google.com/file/d/1G3cxbOC3MS8Yh2K7OyTBr6VtDrKINKhC/view', 'Omelete Completo');
INSERT INTO refeicao (id, calorias, tempo_preparo, modo_preparo, imagem_url, nome) VALUES (9, 180, 2, '1. Separe a porção. 2. Consuma diretamente.', 'https://drive.google.com/file/d/1ERAcJaNs6Z0xzorqEHWgsWNOIt4ctx7H/view', 'Mix de Castanhas');
INSERT INTO refeicao (id, calorias, tempo_preparo, modo_preparo, imagem_url, nome) VALUES (10, 200, 5, '1. Lave a maçã. 2. Corte em fatias. 3. Retire o miolo. 4. Adicione a pasta. 5. Sirva.', 'https://drive.google.com/file/d/1lnjo9eASvPaQBBUhK_bl_JKWdgl_mWIK/view', 'Maçã com Pasta');
INSERT INTO refeicao (id, calorias, tempo_preparo, modo_preparo, imagem_url, nome) VALUES (11, 160, 5, '1. Corte as frutas. 2. Coloque no liquidificador. 3. Adicione o líquido. 4. Bata. 5. Sirva.', 'https://drive.google.com/file/d/10xrajIIZXlZ0SH7CMHc9QZfIF6qlBAbB/view', 'Smoothie');
INSERT INTO refeicao (id, calorias, tempo_preparo, modo_preparo, imagem_url, nome) VALUES (12, 250, 30, '1. Corte o frango. 2. Corte os legumes. 3. Coloque tudo na panela. 4. Cozinhe 25 min. 5. Ajuste o sal.', 'https://drive.google.com/file/d/1yJf67bps2unA6zyLX9DQi-OfG_0gZBzw/view', 'Sopa');
INSERT INTO refeicao (id, calorias, tempo_preparo, modo_preparo, imagem_url, nome) VALUES (13, 280, 15, '1. Lave as folhas. 2. Prepare a proteína. 3. Misture tudo. 4. Tempere. 5. Sirva.', 'https://drive.google.com/file/d/1fSQt8DKz7Tgmc5XPxGsIIpMRa8hbIHOD/view', 'Salada Proteica');
INSERT INTO refeicao (id, calorias, tempo_preparo, modo_preparo, imagem_url, nome) VALUES (14, 220, 10, '1. Quebre os ovos. 2. Bata bem. 3. Aqueça a frigideira. 4. Despeje os ovos. 5. Cozinhe até firmar. 6. Sirva.', 'https://drive.google.com/file/d/1X9gyPVxuzZQfx-gLtfeczgF4Gak8lZ5e/view', 'Omelete Leve');
INSERT INTO refeicao (id, calorias, tempo_preparo, modo_preparo, imagem_url, nome) VALUES (15, 240, 10, '1. Aqueça a frigideira. 2. Espalhe a tapioca. 3. Aguarde firmar. 4. Adicione o recheio. 5. Dobre. 6. Sirva.', 'https://drive.google.com/file/d/1gSkrQ47_kbBUoY33DxaSOSuwOKd8TnPw/view', 'Tapioca com Recheio');
INSERT INTO refeicao (id, calorias, tempo_preparo, modo_preparo, imagem_url, nome) VALUES (17, 190, 3, '1. Coloque o iogurte. 2. Adicione a granola. 3. Misture. 4. Sirva.', 'https://drive.google.com/file/d/1hut_9swLkrZGknZJwThhwnF5x8oohyqS/view', 'Iogurte com Granola');
